//! Embeds the Windows application icon into the `pleochroma-worker` binaries.
//!
//! `assets/icon.ico` (generated by `scripts/make-icons.py`) is embedded as the
//! executable's first icon resource, which Windows also shows on the console window.
//!
//! # Two binaries from one crate
//!
//! - `pleochroma-worker` (`src/main.rs`) is the program. In a build with the `gui` feature
//!   on Windows it is a Windows-subsystem program (`windows_subsystem = "windows"`, set in
//!   `main.rs`): it opens the window and has no console.
//! - `pleochroma-worker-console` (`src/bin/console.rs`) is the console twin: a tiny launcher
//!   that runs the sibling `pleochroma-worker.exe` with the same arguments and standard
//!   streams, waits and returns its exit code, so a terminal keeps its prompt, Ctrl-C and
//!   `%ERRORLEVEL%`. A bare line (no command) starts the window detached instead.
//!
//! Cargo cannot produce a `.com` file, so packaging renames the twin's
//! `pleochroma-worker-console.exe` to `pleochroma-worker.com` and ships it next to
//! `pleochroma-worker.exe`. `cmd` and PowerShell try `.COM` before `.EXE`, so typing
//! `pleochroma-worker` gets the console twin. Other platforms build the twin as a plain
//! `exec` pass-through that nothing needs to ship.
//!
//! # Without the `gui` feature this crate keeps its console
//!
//! No `windows_subsystem = "windows"` (unlike `pleochroma-cut`): `render`, `serve` and
//! `cert` print to stdout, which a Windows-subsystem binary would lose. Only a build with
//! `gui` drops the console, and then the console twin carries the command line.
//!
//! # A missing resource compiler is a warning
//!
//! Embedding needs `rc.exe` or `windres`, which a cross-compile may lack (see
//! `scripts/pgo-bolt-build.sh`). A missing icon must not fail the build.
//!
//! # The target OS decides, not the host
//!
//! A build script runs on the HOST, so `#[cfg(windows)]` would test the wrong machine.
//! `CARGO_CFG_TARGET_OS` gives the TARGET OS; `winresource` picks the target's resource
//! compiler itself (for example `x86_64-w64-mingw32-windres` for the `gnu` triple).

fn main() {
    // The coordinator window (`gui` feature): `ui/app.slint` and everything it imports,
    // including the shared kit and theme (the `pleochroma-ui-kit` crate, imported as
    // `@pleochroma-kit`).
    if std::env::var_os("CARGO_FEATURE_GUI").is_some() {
        slint_build::compile_with_config(
            "ui/app.slint",
            slint_build::CompilerConfiguration::new()
                .with_style("fluent-dark".to_string())
                .with_library_paths(pleochroma_ui_kit::library_paths()),
        )
        .unwrap();
    }
    println!("cargo:rerun-if-env-changed=CARGO_CFG_TARGET_OS");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        embed_icon();
    }
}

/// Embeds `assets/icon.ico` as the executable's Windows icon resource.
///
/// A verbatim twin of `apps/pleochroma-cut/build.rs`'s `embed_icon`: a build script
/// cannot share code across packages without a helper crate both would build first, so
/// an edit to one must be mirrored in the other.
fn embed_icon() {
    println!("cargo:rerun-if-changed=assets/icon.ico");
    let mut res = winresource::WindowsResource::new();
    res.set_icon("assets/icon.ico");
    if let Err(e) = res.compile() {
        println!(
            "cargo:warning=could not embed the application icon ({e}); the binary will build without one"
        );
    }
}
